    """Delete or swap sentence punctuation (. , : ; ! ?). Slashes/hyphens/parentheses are kept."""
    out = []
    for ch in sent:
        if ch in ".,:;!?":
            r = rng.random()
            if r < p_del:
                continue
            if r < p_del + p_swap:
