        for e in WORD_LEVEL_ORDER:
            if e not in edits:
                continue
            rng = _rng(seed, e, i)
            if e == "capitalization":
                s = capitalization(s, rng, protected, seed=seed)
            else:
                s = WORD_OPS[e](s, rng, protected)
